+++ b/training/level-2/L2-023-multi-list/multiList.mjs
@@ -0,0 +1,193 @@
+// OTHRYSL2-023 Multi-list manager
+
+import { promises as fs } from 'fs';
+import { join } from 'path';
+import { randomUUID } from 'crypto';
+
+export function createMultiListStore(filePath) {
+  const file = join(filePath);
+
+  function snapshot() {
+    try {
+      const data = fs.readFileSync(file, 'utf-8');
+      const parsed = JSON.parse(data);
+      return parsed;
+    } catch (e) {
+      if (e.code === 'ENOENT') {
+        return { lists: [] };
+      } else {
+        throw new Error('STATE_CORRUPT');
+      }
+    }
+  }
+
+  function createList(list) {
+    const current = snapshot();
+    const listId = list.id;
+
+    if (current.lists.some(l => l.id === listId)) {
+      throw new Error('DUPLICATE_ID');
+    }
+
+    if (!list.id || !list.name || !list.id.trim() || !list.name.trim()) {
+      throw new Error('INVALID_LIST');
+    }
+
+    const newList = {
+      id: list.id,
+      name: list.name,
+      items: list.items || []
+    };
+
+    const updated = {
+      lists: [...current.lists, newList]
+    };
+
+    writeData(updated);
+    return Object.freeze(JSON.parse(JSON.stringify(newList)));
+  }
+
+  function renameList(listId, newName) {
+    const current = snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOT_FOUND');
+    }
+
+    if (!newName || !newName.trim()) {
+      throw new Error('INVALID_NAME');
+    }
+
+    list.name = newName;
+
+    const updated = {
+      lists: current.lists
+    };
+
+    writeData(updated);
+    return Object.freeze(JSON.parse(JSON.stringify(list)));
+  }
+
+  function deleteList(listId) {
+    const current = snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const updated = {
+      lists: current.lists.filter(l => l.id !== listId)
+    };
+
+    writeData(updated);
+    return Object.freeze(JSON.parse(JSON.stringify(list)));
+  }
+
+  function addItem(listId, item) {
+    const current = snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOT_FOUND');
+    }
+
+    if (!item.id || !item.text || !item.id.trim() || !item.text.trim()) {
+      throw new Error('INVALID_ITEM');
+    }
+
+    const newItem = {
+      id: item.id,
+      text: item.text,
+      done: item.done || false
+    };
+
+    if (list.items.some(i => i.id === newItem.id)) {
+      throw new Error('DUPLICATE_ID');
+    }
+
+    list.items.push(newItem);
+
+    const updated = {
+      lists: current.lists
+    };
+
+    writeData(updated);
+    return Object.freeze(JSON.parse(JSON.stringify(newItem)));
+  }
+
+  function updateItem(listId, itemId, update) {
+    const current = snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const item = list.items.find(i => i.id === itemId);
+    if (!item) {
+      throw new Error('NOT_FOUND');
+    }
+
+    if (update.text !== undefined) {
+      item.text = update.text;
+    }
+
+    if (update.done !== undefined) {
+      item.done = update.done;
+    }
+
+    const updated = {
+      lists: current.lists
+    };
+
+    writeData(updated);
+    return Object.freeze(JSON.parse(JSON.stringify(item)));
+  }
+
+  function removeItem(listId, itemId) {
+    const current = snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const itemIndex = list.items.findIndex(i => i.id === itemId);
+    if (itemIndex === -1) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const item = list.items[itemIndex];
+
+    list.items.splice(itemIndex, 1);
+
+    const updated = {
+      lists: current.lists
+    };
+
+    writeData(updated);
+    return Object.freeze(JSON.parse(JSON.stringify(item)));
+  }
+
+  function writeData(data) {
+    try {
+      const tempFile = file + '.tmp';
+      fs.writeFile(tempFile, JSON.stringify(data, null, 2), 'utf-8');
+      fs.rename(tempFile, file, 'utf-8');
+    } catch (e) {
+      throw new Error('STATE_CORRUPT');
+    }
+  }
+
+  return {
+    snapshot,
+    createList,
+    renameList,
+    deleteList,
+    addItem,
+    updateItem,
+    removeItem
+  };
+}

